const event = $json || {};
const userId = String($('Configuration Mailflow').first().json.mailflow_user_id || '').trim();
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuid.test(userId)) throw new Error('MAILFLOW_USER_ID doit contenir un UUID valide.');
const workflowName = String(event.workflow?.name || 'Workflow n8n').slice(0, 255);
const workflowId = String(event.workflow?.id || 'unknown').slice(0, 80);
const executionId = String(event.execution?.id || `manual-${Date.now()}`).slice(0, 80);
const nodeName = event.execution?.lastNodeExecuted ? String(event.execution.lastNodeExecuted).slice(0, 255) : null;
return [{ json: {
  user_id: userId,
  email_id: null,
  idempotency_key: `n8n-error:${workflowId}:${executionId}`.slice(0, 255),
  workflow_name: workflowName,
  node_name: nodeName,
  error_type: 'workflow_failed',
  status_code: null,
  attempt: null
} }];
